EXPORT ZZT_COMPLEXVEC() BEGIN
LOCAL R,E,O:={};
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,0),3],[0+1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[0+0,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[0+0,-1]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[0+1,3]); THEN E:=1; END;
IF (TYPE(R)==0 OR TYPE(R)==3) THEN
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),ROUND(RE(R),8),ROUND(IM(R),8)}});
ELSE O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}}); END;
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,1),(3,-1)],[0+1,3]); THEN E:=1; END;
IF (TYPE(R)==0 OR TYPE(R)==3) THEN
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),ROUND(RE(R),8),ROUND(IM(R),8)}});
ELSE O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}}); END;
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[0-1,3]); THEN E:=1; END;
IF (TYPE(R)==0 OR TYPE(R)==3) THEN
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),ROUND(RE(R),8),ROUND(IM(R),8)}});
ELSE O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}}); END;
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,0+2,(3,-2)],[0+2,1,4]); THEN E:=1; END;
IF (TYPE(R)==0 OR TYPE(R)==3) THEN
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),ROUND(RE(R),8),ROUND(IM(R),8)}});
ELSE O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}}); END;
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

