O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),ROUND(RE(R),8),ROUND(IM(R),8)}});
ELSE O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}}); END;
HComplex:=1; A:=0; E:=0; R:=-99;
