O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_FAIL(1),ZZT_TICK(2,4)),ZZT_TICK(3,3)],[ZZT_TICK(4,1),ZZT_TICK(5,3)]); THEN E:=1; END;
